/baseline/assets/site.css:
:root{--ink:#0b0f1a;--navy:#101724;--near:#151b27;--blue:#0061fd;--blue-lite:#4c89ff;--white:#fff;--paper:#f7f8f6;--cream:#f0f3f8;--muted:#697385;--line:#e1e5eb;--container:1200px;--radius:20px}
*,*::before,*::after{box-sizing:border-box}
html{scroll-behavior:smooth;scroll-padding-top:90px}
body{margin:0;color:var(--ink);background:var(--white);font:16px/1.6 "DM Sans",Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif;-webkit-font-smoothing:antialiased}
a{color:inherit;text-decoration:none}
button,input{font:inherit}
button{cursor:pointer}
button:disabled{cursor:not-allowed}
img,svg{display:block;max-width:100%}
::selection{background:#abc8ff;color:#071127}
.container{width:min(var(--container),calc(100% - 88px));margin:0 auto}
.eyebrow{font-size:11px;font-weight:800;letter-spacing:.14em;text-transform:uppercase}
.eyebrow.blue{color:var(--blue)}
.eyebrow.light{color:#90b6ff}
.eyebrow i{display:inline-block;width:6px;height:6px;border-radius:50%;background:currentColor;vertical-align:2px;margin-right:9px}
.display{font-family:"Manrope",Inter,system-ui,sans-serif;font-weight:800;letter-spacing:-.069em;line-height:1.075}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:11px;border-radius:100px;padding:0 26px;height:54px;border:1px solid transparent;font-weight:750;font-size:13px;transition:transform .18s,background .18s,border-color .18s;text-align:center;white-space:nowrap}
.btn:hover{transform:translateY(-2px)}
.btn:active{transform:translateY(0)}
.btn.blue{background:var(--blue);color:white;box-shadow:0 12px 28px #0061fd2b}
.btn.blue:hover{background:#0053db}
.btn svg{height:16px;width:16px;stroke-width:1.8}
.skip{position:absolute;top:-110px;left:24px;padding:12px 18px;background:white;z-index:100}
.skip:focus{top:12px}
a:focus-visible,button:focus-visible,summary:focus-visible{outline:3px solid #7caeff;outline-offset:4px}
.topbar{background:var(--ink);color:#fff;position:sticky;top:0;z-index:40;border-bottom:1px solid #ffffff1a;backdrop-filter:blur(16px)}
.topbar .container{height:82px;display:flex;align-items:center;justify-content:space-between;gap:34px}
.brand{display:inline-flex;align-items:center;flex-shrink:0}
.brand img{display:block;width:151px;height:auto}
.nav-links{display:flex;align-items:center;gap:34px;margin-left:auto}
.nav-links a{font-size:12px;color:#b5c0d0;font-weight:700;transition:color .18s}
.nav-links a:hover{color:#fff}
.nav-actions{display:flex;align-items:center;gap:24px}
.login{font-size:12px;font-weight:700;color:#c0c9d8}
.login:hover{color:white}
.nav-actions .btn{height:42px;padding:0 20px;font-size:12px}
.hero{background:var(--ink);color:#fff;position:relative;isolation:isolate;overflow:hidden}
.hero::before{content:"";position:absolute;z-index:-1;inset:0;background:radial-gradient(circle at 88% 48%,#0d347a70 0%,transparent 38%),radial-gradient(circle at 50% 110%,#0e275556,transparent 45%);pointer-events:none}
.chat-window{background:#eef2f8;border:1px solid #4c618244;box-shadow:0 28px 100px #0007;border-radius:22px;overflow:hidden;color:#182638}
.chat-head{height:75px;background:#fff;display:flex;align-items:center;gap:11px;padding:0 21px;border-bottom:1px solid #e5ebf2}
.chat-avatar{width:41px;height:41px;border-radius:13px;background:#eef4ff;display:grid;place-items:center;flex-shrink:0}
.chat-avatar img{width:29px;height:29px;object-fit:contain}
.chat-person{min-width:0}
.chat-person strong{font-size:13px;display:block;line-height:1.3}
.chat-person small{font-size:10px;color:#8191a5}
.online-dot{width:6px;height:6px;border-radius:50%;background:#14a378;display:inline-block;margin-right:5px}
.chat-actions{margin-left:auto;display:flex;gap:12px;align-items:center;color:#7c90a7}
.chat-actions svg{width:18px;height:18px}
.chat-body{padding:25px 21px 22px;min-height:446px;background:linear-gradient(130deg,#eaf0f8,#e9eef8);display:flex;flex-direction:column;gap:13px}
.date-stamp{text-align:center;color:#96a4b8;font-size:10px;letter-spacing:.04em;margin-bottom:4px}
.bubble{font-size:13px;line-height:1.62;padding:13px 16px;max-width:86%;box-shadow:0 3px 8px #17283d09}
.bubble.you{align-self:flex-end;background:#d4e5ff;border-radius:15px 15px 4px 15px}
.bubble.ai{align-self:flex-start;background:white;border-radius:15px 15px 15px 4px}
.bubble small{display:block;text-align:right;color:#97a5b5;font-size:9px;margin-top:6px}
.mini-record{border:1px solid #e7edf4;border-radius:11px;padding:12px 13px;margin-top:10px;background:#f9fbff}
.mini-record .rlabel{display:block;font-size:9px;text-transform:uppercase;letter-spacing:.08em;font-weight:800;color:#2873d5}
.mini-record strong{display:block;font-size:13px;margin:5px 0 3px}
.mini-record span{display:block;color:#78889d;font-size:11px}
.chat-compose{height:62px;padding:11px 16px;background:#fff;display:flex;align-items:center;gap:10px}
.chat-compose>span{flex:1;background:#f2f5f9;border-radius:100px;padding:9px 16px;color:#a6b2c0;font-size:11px}
.chat-compose .send{background:var(--blue);color:white;border-radius:50%;width:34px;height:34px;display:grid;place-items:center}
.chat-compose svg{width:15px;height:15px}
.demo-caption{text-align:right;margin-top:15px;color:#8392a9;font-size:10px;letter-spacing:.03em}
.section{padding:120px 0}
.relief{background:#f7f8f6}
.relief-grid{display:grid;grid-template-columns:minmax(0,.92fr) minmax(0,1.08fr);gap:100px;align-items:start}
.relief h2{font-size:clamp(39px,4.3vw,59px);margin:23px 0 24px;max-width:575px}
.relief h2 em{color:var(--blue);font-style:normal}
.relief-lead{font-size:16px;line-height:1.8;color:#6b7584;max-width:510px}
.pain-rows{padding-top:8px}
.pain-row{border-top:1px solid #d9dee5;padding:26px 0;display:grid;grid-template-columns:35px 1fr;gap:15px;align-items:start}
.pain-row:last-child{border-bottom:1px solid #d9dee5}
.pain-row .num{color:#2070e9;font-size:12px;font-weight:800;line-height:1.8}
.pain-row strong{font-size:19px;letter-spacing:-.035em;display:block;line-height:1.35;font-weight:780}
.pain-row p{color:#748093;font-size:13px;line-height:1.7;margin:7px 0 0;max-width:460px}
.relief-note{margin-top:28px;color:#38619c;font-size:13px;font-weight:750}
.product{background:#f7f8f6}
.how{background:#fff}
.how-inner{display:grid;grid-template-columns:.9fr 1.1fr;gap:75px;align-items:start}
.how h2{font-size:clamp(38px,4.3vw,59px);margin:20px 0 20px}
.how p{font-size:16px;color:#728092;line-height:1.8;max-width:500px}
.steps{display:grid}
.steps>div{display:grid;grid-template-columns:52px 1fr;gap:18px;padding:22px 0;border-bottom:1px solid #e5e9ee}
.steps>div:first-child{border-top:1px solid #e5e9ee}
.steps .step-num{font-size:12px;font-weight:800;color:var(--blue)}
.steps strong{font-size:16px}
.steps p{font-size:12px;line-height:1.7;margin:7px 0 0}
.pricing{background:var(--ink);color:white;position:relative;overflow:hidden}
.pricing::before{content:"";position:absolute;z-index:0;width:650px;height:650px;border-radius:50%;top:-450px;right:-180px;background:#005bff24;filter:blur(30px)}
.pricing .container{position:relative;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,.84fr);gap:75px;align-items:center}
.pricing h2{font-size:clamp(43px,4.6vw,64px);margin:22px 0 20px}
.pricing-copy p{color:#a9b7ca;max-width:480px;font-size:15px;line-height:1.8}
.price-panel{border:1px solid #364253;border-radius:24px;background:#171f2d;padding:40px 42px;box-shadow:0 18px 70px #0004}
.price-panel .p-eyebrow{font-size:10px;letter-spacing:.13em;color:#9fbbeb;font-weight:800}
.amount{display:flex;align-items:baseline;gap:5px;margin:14px 0 16px}
.amount span{font-size:22px;font-weight:760}
.amount strong{font-size:70px;line-height:1.12;font-family:Manrope,Inter,sans-serif;letter-spacing:-.08em}
.amount em{font-size:15px;color:#b5c2d4;font-style:normal;margin-left:4px}
.price-panel p{font-size:13px;color:#aebbd0;margin:0 0 23px;line-height:1.7}
.price-panel .btn{width:100%}
.price-panel .small-print{font-size:10px;color:#879bb8;margin:15px 0 0;line-height:1.5}
.faq{background:#fff}
.faq-grid{display:grid;grid-template-columns:.8fr 1.2fr;gap:105px}
.faq h2{font-size:clamp(40px,4.4vw,60px);margin:22px 0 18px}
.faq-intro{font-size:15px;color:#79869a;line-height:1.8}
.faq-list{border-top:1px solid #e4e9ef}
.faq-list details{border-bottom:1px solid #e4e9ef}
.faq-list summary{padding:24px 0;list-style:none;cursor:pointer;display:flex;gap:20px;align-items:center;justify-content:space-between;font-size:15px;font-weight:740}
.faq-list summary::-webkit-details-marker{display:none}
.faq-list summary span:last-child{font-size:22px;color:var(--blue);font-weight:400}
.faq-list details[open] summary span:last-child{transform:rotate(45deg)}
.faq-list details p{font-size:13px;color:#718096;line-height:1.8;margin:-3px 30px 22px 0}
.endbar{background:#eff4fd;padding:52px 0}
.endbar .container{display:flex;align-items:center;justify-content:space-between;gap:35px}
.endbar strong{font-family:Manrope,sans-serif;font-size:clamp(25px,3vw,39px);line-height:1.2;letter-spacing:-.05em;max-width:660px;display:block}
.endbar p{color:#6f7f92;font-size:13px;margin:9px 0 0}
.footer{background:white;padding:39px 0}
.footer-inner{display:flex;align-items:center;gap:30px;justify-content:space-between}
.footer .brand img{width:128px}
.footer-links{display:flex;gap:24px;flex-wrap:wrap}
.footer-links a{font-size:12px;color:#66758a;font-weight:650}
.footer small{font-size:10px;color:#98a6b9}
@media (max-width:1120px){.relief-grid{gap:60px}
.faq-grid{gap:65px}
.pricing .container{gap:45px}}
@media (max-width:920px){.container{width:calc(100% - 52px)}
.topbar .container{gap:18px}
.nav-links{gap:18px}
.nav-actions{gap:15px}
.topbar .btn{display:none}
.chat-body{padding:20px 14px}
.bubble{font-size:11px}
.relief-grid{gap:35px}
.section{padding:95px 0}
.faq-grid{gap:35px}}
@media (max-width:760px){.container{width:calc(100% - 42px)}
.topbar .container{height:69px}
.topbar .brand img{width:125px}
.nav-links,.nav-actions .login{display:none}
.nav-actions{margin-left:auto}
.chat-body{min-height:390px}
.relief-grid,.how-inner,.pricing .container,.faq-grid{grid-template-columns:1fr;gap:37px}
.section{padding:88px 0}
.relief h2,.how h2,.pricing h2,.faq h2{font-size:clamp(37px,7vw,51px)}
.relief h2{max-width:700px}
.pricing .container{gap:36px}
.price-panel{max-width:600px;width:100%;margin:auto}
.faq-grid{gap:20px}
.endbar .container{align-items:flex-start;flex-direction:column;gap:23px}
.footer-inner{align-items:flex-start;flex-wrap:wrap}}
@media (max-width:470px){.container{width:calc(100% - 36px)}
.chat-head{height:67px;padding:0 14px}
.chat-avatar{width:35px;height:35px}
.chat-body{min-height:385px;padding:15px 12px;gap:10px}
.bubble{font-size:11px;max-width:91%;padding:11px 12px}
.mini-record{padding:10px 11px}
.mini-record strong{font-size:12px}
.chat-compose{height:53px}
.section{padding:75px 0}
.relief h2,.how h2,.pricing h2,.faq h2{font-size:39px}
.relief-lead,.how p{font-size:14px}
.pain-row{padding:21px 0}
.pain-row strong{font-size:17px}
.amount strong{font-size:62px}
.price-panel{padding:28px 25px}
.faq-list summary{padding:20px 0;font-size:14px}
.endbar{padding:45px 0}
.footer{padding:34px 0}
.footer-inner{gap:19px}
.footer-links{gap:15px}}
@media (max-width:360px){.chat-body{min-height:360px}
.price-panel{padding:25px 18px}
.amount strong{font-size:55px}
.endbar .btn{width:100%}}
@media (prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important}
html{scroll-behavior:auto}}
.price-panel{min-width:0}
.xp-stage{max-width:1060px;margin:0 auto;border:1px solid #34435f;border-radius:25px;background:linear-gradient(150deg,#151f33 0%,#10182a 40%,#0b1424 100%);overflow:hidden;box-shadow:0 32px 110px #0008,0 0 64px #174a8d18;position:relative}
.xp-stage::before{content:"";height:1px;position:absolute;left:24px;right:24px;top:0;background:linear-gradient(90deg,transparent,#96c4ff88,transparent);pointer-events:none}
.xp-stage-top{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:17px 23px;border-bottom:1px solid #ffffff14;background:#ffffff05}
.xp-brand-line{display:flex;align-items:center;gap:12px;min-width:0}
.xp-logo{height:41px;width:41px;display:grid;place-items:center;border-radius:13px;background:#192f56;box-shadow:inset 0 1px #ffffff28;flex:0 0 auto}
.xp-logo img{width:32px;height:31px;object-fit:contain}
.xp-brand-line strong{display:block;font-size:15px;line-height:1.2;letter-spacing:.04em;color:#fff}
.xp-brand-line small{display:flex;align-items:center;gap:7px;color:#a5b6ca;font-size:11px;margin-top:5px}
.xp-available{width:7px;height:7px;border-radius:50%;background:#35ca94;box-shadow:0 0 0 3px #35ca9419}
#xpPrev svg{transform:rotate(180deg)}
.xp-scene{min-height:451px;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.07fr);gap:22px;padding:26px}
.xp-scene > *{min-width:0;animation:xp-enter .5s cubic-bezier(.22,1,.36,1) both}
.xp-scene > :nth-child(2){animation-delay:.11s}
.xp-chat-column{display:flex;flex-direction:column;justify-content:center;min-height:380px;min-width:0;padding:16px 0}
.xp-convo-caption{font-size:10px;letter-spacing:.17em;font-weight:800;color:#8facd6;margin:0 0 24px}
.xp-chat-lines{display:flex;flex-direction:column;align-items:flex-start;gap:16px}
.xp-message{width:100%;display:flex;align-items:flex-start;gap:10px;animation:xp-enter .43s both}
.xp-message.xp-in{animation-delay:.28s}
.xp-message.xp-out{justify-content:flex-end}
.xp-bubble{position:relative;border-radius:17px;font-size:13px;line-height:1.62;padding:14px 17px;max-width:min(100%,420px);box-shadow:0 8px 25px #0003}
.xp-out .xp-bubble{border-radius:17px 17px 5px 17px;background:linear-gradient(130deg,#144b47,#183e40);border:1px solid #266e68;color:#f0fafa}
.xp-in .xp-bubble{border-radius:6px 17px 17px 17px;background:#242e41;color:#eef3fc;border:1px solid #35445e}
.xp-agent-icon{width:31px;height:31px;flex:0 0 31px;padding:5px;object-fit:contain;background:#162c51;border-radius:10px}
.xp-time{display:block;margin-top:7px;font-size:10px;color:#97aaba;text-align:right}
.xp-time b{color:#75b7ff;font-weight:750}
.xp-chat-note{margin-top:28px;color:#7f8ea8;font-size:11px}
.xp-audio-line{display:flex;gap:10px;align-items:center;padding:2px 0 11px}
.xp-voice-play{display:grid;place-items:center;width:29px;height:29px;border-radius:50%;background:#2b8e81;color:#fff;font-size:10px;flex:0 0 29px}
.xp-voice-wave{display:flex;align-items:center;gap:3px;max-width:167px;min-width:0;height:31px}
.xp-voice-wave i{display:block;width:3px;flex:1;min-width:2px;height:var(--h);border-radius:5px;background:#76dfd0;transform-origin:center;animation:xp-wave 1.4s ease-in-out infinite alternate;animation-delay:calc(var(--h) * -29ms)}
.xp-audio-length{font-size:10px;color:#b3e3db}
.xp-voice-transcription{color:#eff9f7}
.xp-result-column{display:flex;align-items:stretch}
.xp-result{width:100%;min-width:0;align-self:center;border-radius:18px;border:1px solid #456184;background:linear-gradient(148deg,#1c2c47,#121d31);padding:23px;box-shadow:0 16px 50px #0003,inset 0 1px #ffffff12;position:relative;overflow:hidden}
.xp-result::after{content:"";position:absolute;width:190px;height:190px;bottom:-155px;right:-100px;border-radius:50%;box-shadow:0 0 75px 38px #2368dc28;pointer-events:none}
.xp-result-header{display:flex;gap:10px;align-items:center;flex-wrap:wrap;color:#dbe7fb;font-size:12px;font-weight:780;padding-bottom:18px;border-bottom:1px solid #ffffff19}
.xp-result-header > svg{width:18px;height:18px;color:#73a9ff}
.xp-success-badge{display:inline-flex;align-items:center;gap:5px;background:#124533;color:#84f3b7;border-radius:99px;padding:5px 8px;margin-left:auto;font-size:10px;white-space:nowrap}
.xp-success-badge svg{width:13px;height:13px}
.xp-result-period{color:#a3b4cd;font-size:10px;margin-left:auto;font-weight:650}
.xp-event{display:flex;gap:14px;justify-content:space-between;align-items:center;margin:28px 0}
.xp-field-label,.xp-total-label{display:block;color:#85a9df;font-size:10px;letter-spacing:.13em;font-weight:850;margin:0 0 10px}
.xp-event h3{font-size:clamp(23px,3vw,33px);line-height:1.2;letter-spacing:-.04em;margin:0 0 8px;color:white}
.xp-event p{color:#b9c8dc;margin:0;font-size:12px}
.xp-reminder-row{display:flex;align-items:center;gap:12px;padding-top:18px;border-top:1px solid #ffffff1b;color:#deebff;font-size:12px}
.xp-soft-icon{height:34px;width:34px;background:#293b55;border-radius:11px;display:grid;place-items:center;flex:0 0 34px}
.xp-soft-icon svg{height:17px;width:17px}
.xp-reminder-row > svg{width:17px;height:17px;color:#9ebfff;flex-shrink:0}
.xp-reminder-row strong,.xp-reminder-row small{display:block}
.xp-reminder-row small{font-size:11px;color:#a9b9d0;margin-top:4px}
.xp-state-dot{height:14px;width:27px;display:inline-block;background:#246de1;border-radius:30px;margin-left:auto;flex:0 0 27px;position:relative}
.xp-state-dot::before{content:"";height:10px;width:10px;border-radius:50%;background:white;position:absolute;right:2px;top:2px}
.xp-card-caption{font-size:10px;color:#90a7c8;margin:18px 0 0;line-height:1.5}
.xp-task-card{display:flex;align-items:center;gap:12px;padding:18px 0;border-bottom:1px solid #ffffff17}
.xp-task-card h3,.xp-task-card strong{font-size:14px;color:#f0f5fe;margin:0 0 4px;display:block}
.xp-task-card p{font-size:11px;color:#9cacbf;margin:0}
.xp-task-check{border:2px solid #678dbe;height:22px;width:22px;flex:0 0 22px;border-radius:6px;display:grid;place-items:center}
.xp-task-check.done{background:#244a81;border-color:#467dda}
.xp-task-check svg{width:14px;height:14px}
.xp-task-dim{opacity:.73}
.xp-task-label{background:#24417a;color:#a1c6ff;border-radius:99px;padding:5px 8px;font-size:10px;margin-left:auto}
.xp-task-progress{padding:16px 0}
.xp-progress-title{display:flex;justify-content:space-between;align-items:center;gap:10px;font-size:11px;color:#a8b9cf;margin-bottom:11px}
.xp-progress-title strong{color:#d6e5f8;font-size:11px}
.xp-task-track{height:7px;width:100%;display:block;border-radius:9px;background:#2b3850;overflow:hidden}
.xp-task-track i{display:block;height:100%;width:50%;border-radius:9px;background:#5393ff;animation:xp-taskgrow 1s .35s ease both}
.xp-total{margin:4px 0 16px;font-size:clamp(28px,3.4vw,40px);font-weight:800;color:#fff;line-height:1.1;letter-spacing:-.055em}
.xp-total-label{margin-top:21px}
.xp-expense-row{display:flex;justify-content:space-between;gap:12px;align-items:center;margin:12px 0 5px;font-size:12px}
.xp-expense-row strong,.xp-expense-row small{display:block}
.xp-expense-row strong{color:#ecf3fb;font-size:12px}
.xp-expense-row small{color:#92a6bf;margin-top:2px;font-size:10px}
.xp-expense-row b{color:#fff;white-space:nowrap}
.xp-expense-track{height:5px;border-radius:99px;background:#303e57;overflow:hidden}
.xp-expense-track i{display:block;background:#5e9eff;width:var(--pct);height:100%;border-radius:99px;transform-origin:left;animation:xp-bar-grow .9s .26s both}
.xp-receipt-paper{margin-top:19px;padding:18px;background:#edf3ff;color:#26354f;border-radius:12px;border:1px solid #d8e4fa;position:relative}
.xp-paper-top{color:#6b809d;font-size:10px;font-weight:750;letter-spacing:.13em;display:block;margin-bottom:19px}
.xp-receipt-paper .xp-field-label{color:#617fae;font-size:9px}
.xp-receipt-paper h3{font-size:clamp(28px,3vw,38px);letter-spacing:-.055em;margin:0 0 16px;color:#0d2345}
.xp-paper-rule{border-top:1px dashed #abc1df;margin:16px 0}
