(()=>{
'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
let scrollLock=null;
function lockScroll(){
 if(scrollLock)return;
 scrollLock={y:window.scrollY,style:document.body.getAttribute('style')};
 Object.assign(document.body.style,{position:'fixed',top:`-${scrollLock.y}px`,left:'0',right:'0',width:'100%',overflow:'hidden'});
}
function unlockScroll(){
 if(!scrollLock)return;
 const saved=scrollLock;scrollLock=null;
 if(saved.style===null)document.body.removeAttribute('style');else document.body.setAttribute('style',saved.style);
 const style=document.documentElement.style.scrollBehavior;
 document.documentElement.style.scrollBehavior='auto';window.scrollTo(0,saved.y);document.documentElement.style.scrollBehavior=style;
}
const menu=$('#mobileNav'),toggle=$('#toggleMenu'),shade=$('#mobileNavShade'),header=$('.topbar');
let menuOpen=false,closeTimer=0,frame=0,inertState=[];
const focusable='a[href],button:not([disabled]),input:not([disabled]),select,textarea,[tabindex="0"]';
function backgroundOff(){
 const elements=[$('main'),$('.footer'),$('.skip'),header.querySelector('.brand'),...header.querySelectorAll('.nav-links,.nav-actions .login,.nav-actions .btn')].filter(Boolean);
 inertState=elements.map(el=>[el,el.inert]);elements.forEach(el=>{el.inert=true});
}
function backgroundOn(){inertState.forEach(([el,prior])=>{el.inert=prior});inertState=[];}
function setMenu(open,{restore=true,immediate=false}={}){
 if(!menu||!toggle)return;
 open=!!open&&matchMedia('(max-width:760px)').matches;
 clearTimeout(closeTimer);cancelAnimationFrame(frame);
 if(open){
  if(!menuOpen){lockScroll();backgroundOff();}
  menuOpen=true;menu.hidden=false;menu.inert=false;shade.hidden=false;
  header.setAttribute('role','dialog');header.setAttribute('aria-modal','true');header.setAttribute('aria-label','Navegação do Astra');
