 }
}
if(menu&&toggle){
 menu.querySelectorAll('a').forEach((a,i)=>a.style.setProperty('--nav-i',String(i)));
 toggle.addEventListener('click',()=>setMenu(!menuOpen));
 shade.addEventListener('click',()=>setMenu(false));
 menu.addEventListener('click',e=>{
  const link=e.target.closest('a');if(!link)return;
  const id=link.getAttribute('href');
  if(id?.startsWith('#')){
   const target=document.getElementById(id.slice(1));if(!target)return;
   e.preventDefault();setMenu(false,{restore:false,immediate:true});
