 form.elements.requestId.value=crypto.randomUUID();
 const contact=kind==='contato';$('#contactField').hidden=!contact;form.elements.message.required=contact;
 $('#leadTitle').textContent=contact?'Fale com a equipe Astra':'Saiba quando seu Astra estiver disponível';
 $('#leadIntro').textContent=contact?'Registre sua dúvida e um e-mail para retorno. Não envie senhas, documentos ou dados bancários.':'Deixe seu e-mail para receber um aviso sobre a disponibilidade. O cadastro é gratuito e não inicia uma assinatura.';
 $('#consentLabel').textContent=contact?'Autorizo o uso deste e-mail para responder à minha solicitação.':'Autorizo um contato por e-mail sobre a disponibilidade do Astra.';
 $('#leadSubmit').textContent=contact?'Enviar solicitação':'Quero ser avisado';
 lockScroll();dlg.showModal();$('#leadTitle').focus({preventScroll:true});
 formToken='';token().then(t=>{formToken=t}).catch(()=>{});
 track(contact?'contact_open':'interest_open');
}
if(dlg){
 $$('[data-open-plan],[data-open-contact]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();openLead(b.hasAttribute('data-open-contact')?'contato':'interesse')}));
 dlg.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>dlg.close()));
 dlg.addEventListener('click',e=>{if(e.target===dlg){const r=dlg.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dlg.close()}});
