   const payload=Object.fromEntries(new FormData(form));payload.consent=form.elements.consent.checked;
   const r=await fetch('/api/interesse',{method:'POST',headers:{'Content-Type':'application/json','X-Astra-Form-Token':formToken},body:JSON.stringify(payload),signal:requestController.signal});
   const data=await r.json().catch(()=>({}));
   if(!r.ok){if(r.status===403)formToken='';throw Error(data.error||'Não foi possível enviar. Tente novamente.');}
   form.hidden=true;success.hidden=false;
   $('#receipt').textContent=data.receipt;
   const cancel=$('#cancelLink');cancel.href='/remover#'+data.cancellationToken;
   $('#successTitle').textContent=payload.intent==='contato'?'Solicitação registrada.':'Seu interesse foi registrado.';
   $('#successTitle').focus({preventScroll:true});
  }catch(err){status.textContent=err.name==='AbortError'?'A conexão demorou mais que o esperado. Tente novamente; seu protocolo evita duplicidade.':err.message;status.focus({preventScroll:true})}
