 remove.disabled=!/^[a-f0-9]{64}$/.test(value);
 remove.addEventListener('click',async()=>{
  remove.disabled=true;
  try{const r=await fetch('/api/remover',{method:'POST',headers:{'Content-Type':'application/json','X-Astra-Form-Token':await token()},body:JSON.stringify({token:value})});if(!r.ok)throw Error();$('#removeStatus').textContent='Solicitação removida ou já inexistente. Nenhum novo contato será feito por esse cadastro.'}
  catch{$('#removeStatus').textContent='Não foi possível remover agora. Tente novamente.';remove.disabled=false;}
 });
}
if(dlg && ['#contato','#interesse'].includes(location.hash))openLead(location.hash==='#contato'?'contato':'interesse');
