.astra-section-head h2 em,.astra-personas-section h2 em,.astra-trust-section h2 em{color:#0866ef;font-style:normal}
.astra-section-head p,.astra-personas-section p{color:#54627b;font-size:clamp(15px,1.5vw,18px);line-height:1.55}
.astra-demo-grid{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(245px,.85fr);align-items:center;gap:24px;max-width:1110px;margin:auto}
