.astra-tabs button{font:750 12px/1.3 "DM Sans",sans-serif;border:0;border-bottom:3px solid transparent;background:transparent;color:#677791;white-space:nowrap;padding:11px 12px 13px;cursor:pointer}
.astra-tabs button[aria-selected="true"]{color:#065de1;border-color:#0866ef;background:#f7faff}
