.astra-category-bar i:nth-child(1){background:#005cff}.astra-category-bar i:nth-child(2){background:#4597ff}.astra-category-bar i:nth-child(3){background:#92c4ff}.astra-category-bar i:nth-child(4){background:#c9dafa}
