 .astra-tabs{padding:5px 6px 0}
 .astra-tabs button{font-size:11px;padding:10px 9px}
 .astra-view{padding:18px 14px;min-height:260px}
 .astra-view-heading{display:block}
 .astra-demo-tag{display:inline-block;margin-top:8px}
 .astra-metrics{gap:8px;margin-top:17px}
 .astra-metric{padding:13px 12px}
 .astra-metric strong{font-size:16px}
 .astra-chat-preview{padding:15px}
 .astra-personas-section{padding:64px 0}
 .astra-personas-section h2{font-size:33px}
 .astra-persona-buttons button{font-size:12px;padding:10px 12px}
 .astra-persona-preview{padding:17px;min-height:0}
 .astra-trust-section{padding:56px 0}
 .astra-trust-grid{grid-template-columns:1fr;gap:11px}
 .astra-trust-grid>div{padding:19px}
 .astra-more-stories{padding:20px 16px 52px}
 .astra-more-stories button{width:100%;max-width:355px}
}
@media(prefers-reduced-motion:reduce){.astra-persona-buttons button,.astra-try-buttons button{transition:none}}

.astra-hero-purchase-note{color:#a7bde4;text-align:center;font-size:11px;line-height:1.5;margin:9px auto 0}
@media(max-width:640px){#inicio .hero-text>p{max-width:340px;margin-left:auto;margin-right:auto}}

