(function () {
  'use strict';
  if (document.documentElement.dataset.astraLandingV2) return;
  document.documentElement.dataset.astraLandingV2 = '1';

  const CHECKOUT = 'https://pay.cakto.com.br/CubL455';
  const $ = (selector, root = document) => root.querySelector(selector);
  const all = (selector, root = document) => [...root.querySelectorAll(selector)];
  const checkoutLink = (text, cls = 'btn blue') => {
    const a = document.createElement('a');
    a.className = cls;
    a.href = CHECKOUT;
    a.target = '_blank';
    a.rel = 'noopener noreferrer';
    a.textContent = text;
    a.setAttribute('aria-label', text + ' (abre checkout seguro da Cakto em outra aba)');
    return a;
  };

  function upgradeCheckout() {
    const originalHero = $('#inicio .hero-cta a.btn.blue');
    if (originalHero) originalHero.replaceWith(checkoutLink('Assinar Astra'));
    const nav = $('.topbar a.btn.blue');
    if (nav) nav.replaceWith(checkoutLink('Assinar Astra', 'btn blue astra-nav-buy'));
    const mobilePlan = $('.mobile-nav-link[href="#plano"]');
    if (mobilePlan) {
      mobilePlan.textContent = 'Assinar Astra';
      mobilePlan.href = CHECKOUT;
      mobilePlan.target = '_blank';
      mobilePlan.rel = 'noopener noreferrer';
    }
    const price = $('#plano .price-panel');
    if (price) {
      const label = $('.p-eyebrow', price);
      if (label) label.textContent = 'ASSINATURA ASTRA';
      const oldBtn = $('[data-open-plan]', price);
      const link = checkoutLink('Assinar pelo checkout da Cakto', 'btn blue astra-price-buy');
      if (oldBtn) {
        oldBtn.parentNode.insertBefore(link, oldBtn);
        oldBtn.classList.remove('blue');
        oldBtn.classList.add('astra-waitlist');
        oldBtn.textContent = 'Prefiro receber novidades';
      } else {
        price.append(link);
      }
      const note = $('.small-print', price);
      if (note) note.textContent = 'Produto: R$ 19,90. O checkout da Cakto informa taxa de serviço de R$ 0,99 (total R$ 20,89). O acesso não é liberado automaticamente: a ativação será manual após confirmação do pagamento, até configurarmos os webhooks.';
    }
    const footer = $('.endbar .container');
    if (footer) footer.append(checkoutLink('Assinar Astra', 'btn blue astra-footer-buy'));
    const next = $('#historia-financas .story-next');
    if (next) next.firstChild.textContent = 'Veja como funciona com lembretes ';
  }

  const samples = {
    gasto: {
      label:'Registrar gasto',
      request:'Astra, gastei R$ 45 de gasolina.',
      response:'Registrado! R$ 45,00 em Transporte.',
      card:'Seu painel foi atualizado com a nova despesa.',
      time:'10:24'
    },
    lembrete: {
      label:'Criar lembrete',
      request:'Astra, me lembra de pagar a internet amanhã às 10h.',
      response:'Combinado! Vou te lembrar amanhã às 10h.',
      card:'Conta de internet · Amanhã, 10h',
      time:'10:25'
    },
    rotina: {
      label:'Organizar meu dia',
      request:'Astra, quais são meus compromissos de hoje?',
      response:'Aqui está seu resumo de hoje.',
      card:'09h Reunião · 14h Dentista · 18h Pagar fatura',
      time:'10:26'
    }
  };

  function renderHeroSample(key) {
    const chat = $('#inicio .chat-body');
    const data = samples[key];
    if (!chat || !data) return;
    chat.innerHTML = '<div class="date-stamp">EXEMPLO DE CONVERSA</div>' +
      '<div class="bubble you">' + data.request + '<small>' + data.time + '</small></div>' +
      '<div class="bubble ai">' + data.response + '<div class="mini-record"><span class="rlabel">Astra organizou</span><strong>' + data.card + '</strong></div><small>' + data.time + '</small></div>';
    all('.astra-try button').forEach(btn => {
      const chosen = btn.dataset.sample === key;
      btn.setAttribute('aria-pressed', String(chosen));
      btn.classList.toggle('selected', chosen);
    });
  }

  function enhanceHero() {
    const cta = $('#inicio .hero-cta');
    if (!cta) return;
    const paragraph = $('#inicio .hero-text > p');
    if (paragraph) paragraph.innerHTML = 'Agenda, finanças e lembretes direto no WhatsApp. <strong>Você fala. O Astra organiza.</strong>';
    const secondary = $('#inicio .hero-cta .hero-secondary');
    if (secondary) { secondary.href = '#painel'; secondary.textContent = 'Ver o Astra funcionando'; }
    cta.insertAdjacentHTML('afterend',
      '<p class="astra-hero-purchase-note">Pagamento via Cakto. Acesso com ativação manual.</p><div class="astra-try" aria-label="Experimente exemplos de pedidos ao Astra">' +
        '<span class="astra-try-label">Experimente uma conversa</span>' +
        '<div class="astra-try-buttons">' +
        Object.entries(samples).map(([key,data]) =>
          '<button type="button" data-sample="' + key + '" aria-pressed="false">' + data.label + '</button>'
        ).join('') +
        '</div><small>Demonstração interativa com dados fictícios.</small>' +
      '</div>');
    all('.astra-try button').forEach(btn => btn.addEventListener('click', () => renderHeroSample(btn.dataset.sample)));
    renderHeroSample('gasto');
    const demo = $('#inicio .hero-demo');
    if (demo) demo.setAttribute('aria-label', 'Conversa fictícia interativa do Astra');
  }

  const views = {
    inicio: { title:'Tudo em um só lugar', desc:'Uma visão rápida para começar seu dia.', items:[
      ['Próximo compromisso','Dentista · 14h'],
      ['Tarefas pendentes','3 tarefas'],
      ['Lembrete do dia','Pagar fatura · 18h'],
      ['Saldo registrado','R$ 1.954,10']
    ], message:'Astra, organiza meu dia.', reply:'Pronto! Separei seus compromissos, tarefas e lembretes.' },
    transacoes: { title:'Seus registros financeiros', desc:'O que você escreve também aparece no painel.', items:[
      ['Último gasto','Gasolina · R$ 45,00'],
      ['Entradas do mês','R$ 3.200,00'],
      ['Saídas do mês','R$ 1.245,90'],
      ['Saldo do mês','R$ 1.954,10']
    ], message:'Gastei R$ 45 de gasolina.', reply:'Anotado em Transporte. Seu resumo foi atualizado.' },
    categorias: { title:'Entenda para onde vai', desc:'Cada categoria organizada com clareza.', items:[
      ['Alimentação','40%'],['Transporte','20%'],['Contas','25%'],['Outros','15%']
    ], message:'Quanto gastei por categoria?', reply:'Aqui está seu resumo, organizado por categoria.' },
    agenda: { title:'Seus horários em ordem', desc:'Compromissos e lembretes em uma única visão.', items:[
      ['09:00','Reunião de equipe'],['14:00','Consulta com dentista'],
      ['18:00','Pagar fatura'],['Amanhã','Renovar assinatura']
    ], message:'Me lembra da consulta às 14h.', reply:'Lembrete registrado para sua consulta às 14h.' },
    perfil: { title:'Uma rotina do seu jeito', desc:'Suas informações e preferências de organização.', items:[
      ['Preferência','Lembretes pelo WhatsApp'],['Formato','Texto ou áudio'],
      ['Registros','Organizados no painel'],['Conta','Acesso protegido']
    ], message:'Astra, o que você sabe sobre minha rotina?', reply:'Posso consultar os registros que você escolheu salvar.' }
  };
  const tabNames = {inicio:'Início',transacoes:'Transações',categorias:'Categorias',agenda:'Agenda',perfil:'Perfil'};
  const icon = '<img src="/baseline/assets/brand-bc825f0438ab.svg" width="30" height="30" alt="">';
  function renderView(key) {
    const view = views[key]; const area=$('#astra-view-panel'), conversation=$('#astra-panel-chat');
    if(!area || !view) return;
    area.setAttribute('aria-label', 'Prévia de ' + tabNames[key]);
    area.innerHTML = '<div class="astra-view-heading"><div><span class="astra-mini-eyebrow">PAINEL ASTRA · EXEMPLO</span>' +
      '<h3>' + view.title + '</h3><p>' + view.desc + '</p></div>' +
      '<span class="astra-demo-tag">Dados ilustrativos</span></div>' +
      '<div class="astra-metrics">' + view.items.map(([k,v]) =>
      '<div class="astra-metric"><span>' + k + '</span><strong>' + v + '</strong></div>'
      ).join('') + '</div>' +
      (key==='categorias' ? '<div class="astra-category-bar"><i style="width:40%"></i><i style="width:20%"></i><i style="width:25%"></i><i style="width:15%"></i></div>' : '') +
      '<div class="astra-panel-bottom">Uma mensagem no WhatsApp. Tudo organizado no painel.</div>';
    if (conversation) conversation.innerHTML = '<div class="astra-chat-top">' + icon + '<strong>Astra</strong><small>Exemplo de conversa</small></div>' +
      '<div class="astra-chat-bubble out">' + view.message + '</div>' +
      '<div class="astra-chat-bubble in">' + view.reply + '</div><small>Simulação demonstrativa</small>';
    all('#astra-dashboard [role="tab"]').forEach(b => {
      const active=b.dataset.view===key;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;
    });
  }
  function addDashboard() {
    const where=$('#funcionalidades');
    if(!where) return;
    const html='<section id="painel" class="astra-panel-section" aria-labelledby="astra-panel-title"><div class="container">' +
      '<div class="astra-section-head"><span class="astra-mini-eyebrow">DO WHATSAPP AO SEU PAINEL</span>' +
      '<h2 id="astra-panel-title">Você conversa. <em>O Astra organiza.</em></h2>' +
      '<p>Veja como uma simples mensagem se transforma em informação útil para sua rotina.</p></div>' +
      '<div class="astra-demo-grid"><div class="astra-dashboard" id="astra-dashboard">' +
      '<div class="astra-dash-head">' + icon + '<strong>Astra</strong><span>Prévia do painel</span></div>' +
      '<div class="astra-tabs" role="tablist" aria-label="Áreas do painel Astra">' +
      Object.entries(tabNames).map(([key,name])=>'<button role="tab" data-view="'+key+'" aria-controls="astra-view-panel" aria-selected="false">'+name+'</button>').join('') +
      '</div><div id="astra-view-panel" class="astra-view" role="tabpanel" tabindex="0"></div></div>' +
      '<div class="astra-conversation-side"><span class="astra-mini-eyebrow">A MENSAGEM QUE VIROU RESULTADO</span>' +
      '<div id="astra-panel-chat" class="astra-chat-preview" aria-live="polite"></div>' +
      '<p>Visualização ilustrativa. Nenhuma informação real é enviada nesta demonstração.</p></div></div>' +
      '</div></section>';
    where.insertAdjacentHTML('afterend',html);
    all('#astra-dashboard [role="tab"]').forEach(b=>b.addEventListener('click',()=>renderView(b.dataset.view)));
    renderView('inicio');
  }

  const people = {
    estudantes:['Estudantes','Lembra da prova de amanhã às 7h e do trabalho de sexta.','Prova, trabalho e horário de estudo organizados.'],
    profissionais:['Profissionais','Astra, me lembra da reunião e das minhas tarefas de hoje.','Reunião e tarefas adicionadas à sua rotina.'],
    empreendedores:['Empreendedores','Preciso enviar uma proposta às 14h e cobrar uma fatura sexta.','Proposta e cobrança registradas com lembretes.'],
    familias:['Famílias','Adiciona leite à lista e lembra da consulta da minha filha.','Lista de compras e compromisso organizados.'],
    financas:['Finanças','Astra, gastei R$ 38,50 no almoço.','Despesa registrada em Alimentação.'],
    saude:['Saúde e bem-estar','Me lembra de tomar o remédio às 14h.','Lembrete de medicamento criado para as 14h.']
  };
  function setPersona(key) {
    const d=people[key];const dest=$('#astra-persona-conversation');if(!d||!dest)return;
    dest.innerHTML='<div class="astra-persona-chat-top">'+icon+' <strong>Astra</strong> <span>Conversa ilustrativa</span></div>' +
      '<div class="astra-chat-bubble out">'+d[1]+'</div><div class="astra-chat-bubble in">'+d[2]+'</div>';
    all('#astra-personas [data-persona]').forEach(btn=>btn.setAttribute('aria-pressed',String(btn.dataset.persona===key)));
  }
  function addPersonas() {
    const anchor=$('#experimente');
    if(!anchor) return;
    anchor.insertAdjacentHTML('beforebegin','<section id="para-quem" class="astra-personas-section" aria-labelledby="astra-personas-title"><div class="container astra-personas-layout">' +
      '<div><span class="astra-mini-eyebrow">ASTRA PARA A VIDA REAL</span><h2 id="astra-personas-title">Um assistente. <em>Várias rotinas.</em></h2>' +
      '<p>Escolha uma situação e veja como o Astra pode organizar as informações de cada dia.</p>' +
      '<div class="astra-persona-buttons" id="astra-personas" aria-label="Escolha uma rotina">' +
      Object.entries(people).map(([key,v])=>'<button type="button" data-persona="'+key+'" aria-pressed="false">'+v[0]+'</button>').join('')+
      '</div></div><div class="astra-persona-preview"><div id="astra-persona-conversation" aria-live="polite"></div>' +
      '<small>Exemplos fictícios para demonstração, não uma conversa com IA em tempo real.</small></div></div></section>');
    all('#astra-personas [data-persona]').forEach(b=>b.addEventListener('click',()=>setPersona(b.dataset.persona)));
    setPersona('estudantes');
  }

  function addTrust() {
    const pricing=$('#plano');
    if(!pricing)return;
    pricing.insertAdjacentHTML('beforebegin','<section id="confianca" class="astra-trust-section"><div class="container"><div class="astra-trust-title">' +
      '<span class="astra-mini-eyebrow">CLAREZA EM CADA ETAPA</span><h2>Seu dia organizado, <em>com suas escolhas.</em></h2></div>' +
      '<div class="astra-trust-grid"><div><strong>Seus próprios registros</strong><p>Você escolhe o que quer guardar e consultar.</p></div>' +
      '<div><strong>Informações no painel</strong><p>Veja sua rotina e seus lançamentos em um só lugar.</p></div>' +
      '<div><strong>Privacidade transparente</strong><p><a href="/privacidade">Conheça nossa política</a> e como solicitar a exclusão de dados.</p></div></div></div></section>');
  }

  function compactStories() {
    const more=['historia-comprovantes','historia-relatorios'];
    const tasks=$('#historia-tarefas');
    if(!tasks)return;
    more.forEach(id=>{const sec=$('#'+id);if(sec){sec.hidden=true;sec.classList.add('astra-extra-story');}});
    tasks.insertAdjacentHTML('afterend','<div class="astra-more-stories"><button id="astra-show-extras" type="button" aria-expanded="false">Ver mais exemplos: fotos e relatórios <span aria-hidden="true">+</span></button></div>');
    const show=()=>{more.forEach(id=>{const el=$('#'+id);if(el)el.hidden=false;});const btn=$('#astra-show-extras');if(btn){btn.setAttribute('aria-expanded','true');btn.textContent='Exemplos adicionais exibidos';btn.disabled=true;}};
    $('#astra-show-extras')?.addEventListener('click',show);
    all('a[href="#historia-comprovantes"], a[href="#historia-relatorios"]').forEach(a=>a.addEventListener('click',show));
    const intro=$('#experimente .story-intro-overline');
    if(intro)intro.textContent='ASTRA NA PRÁTICA / CONVERSAS REAIS DO COTIDIANO';
    const sub=$('#experimente .story-intro-layout > p');
    if(sub)sub.textContent='Três situações para entender o funcionamento do Astra. Explore outras possibilidades quando quiser.';
  }

  try {
    upgradeCheckout();
    enhanceHero();
    addDashboard();
    addPersonas();
    compactStories();
    addTrust();
    const nav=$('.topbar nav');
    if(nav&&!nav.querySelector('a[href="#painel"]')){const a=document.createElement('a');a.href='#painel';a.textContent='Painel';const target=nav.querySelector('a[href="#plano"]');nav.insertBefore(a,target||null);}
  } catch(error) {
    console.error('ASTRA_LANDING_ENHANCEMENT_FAILED', error);
  }
})();
